// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract SecureVault {
    struct Credential {
        bytes32 passwordHash;
        uint256 lastAttempt;
        uint8 failedAttempts;
        bool locked;
    }

    struct AuditEntry {
        address actor;
        bytes32 action;
        uint256 timestamp;
        bool success;
    }

    mapping(address => Credential) private credentials;
    mapping(address => uint256) private balances;
    AuditEntry[] public auditLog;

    uint8 public constant MAX_ATTEMPTS = 5;
    uint256 public constant LOCKOUT_DURATION = 1 hours;
    uint256 public constant RATE_LIMIT_WINDOW = 30 seconds;

    event AuthAttempt(address indexed user, bool success);
    event AccountLocked(address indexed user, uint256 until);
    event AuditLogged(uint256 indexed entryId, address actor);

    modifier notLocked(address user) {
        if (credentials[user].locked) {
            require(
                block.timestamp >= credentials[user].lastAttempt + LOCKOUT_DURATION,
                "Account is locked"
            );
            credentials[user].locked = false;
            credentials[user].failedAttempts = 0;
        }
        _;
    }

    modifier rateLimited(address user) {
        require(
            block.timestamp >= credentials[user].lastAttempt + RATE_LIMIT_WINDOW,
            "Rate limited: too many requests"
        );
        _;
    }

    function register(bytes32 _passwordHash) external {
        require(credentials[msg.sender].passwordHash == bytes32(0), "Already registered");
        credentials[msg.sender].passwordHash = _passwordHash;
        _logAudit(msg.sender, keccak256("REGISTER"), true);
    }

    function deposit() external payable {
        require(credentials[msg.sender].passwordHash != bytes32(0), "Not registered");
        balances[msg.sender] += msg.value;
        _logAudit(msg.sender, keccak256("DEPOSIT"), true);
    }

    function authenticate(
        bytes32 _passwordHash
    ) external notLocked(msg.sender) rateLimited(msg.sender) returns (bool) {
        address _target = msg.sender;
        credentials[_target].lastAttempt = block.timestamp;

        if (credentials[_target].passwordHash == _passwordHash) {
            credentials[_target].failedAttempts = 0;
            _logAudit(_target, keccak256("AUTH_SUCCESS"), true);
            emit AuthAttempt(_target, true);
            return true;
        } else {
            credentials[_target].failedAttempts += 1;
            _logAudit(_target, keccak256("AUTH_FAILURE"), false);
            emit AuthAttempt(_target, false);

            if (credentials[_target].failedAttempts >= MAX_ATTEMPTS) {
                credentials[_target].locked = true;
                emit AccountLocked(_target, block.timestamp + LOCKOUT_DURATION);
            }
            return false;
        }
    }

    function withdraw(uint256 _amount, bytes32 _passwordHash) external notLocked(msg.sender) rateLimited(msg.sender) {
        require(credentials[msg.sender].passwordHash != bytes32(0), "Not registered");
        require(balances[msg.sender] >= _amount, "Insufficient balance");
        require(_verifyCredential(msg.sender, _passwordHash), "Authentication failed");

        balances[msg.sender] -= _amount;
        _logAudit(msg.sender, keccak256("WITHDRAW"), true);

        (bool sent, ) = payable(msg.sender).call{value: _amount}("");
        require(sent, "Transfer failed");
    }

    function _verifyCredential(
        address _user,
        bytes32 _passwordHash
    ) internal returns (bool) {
        if (credentials[_user].passwordHash == _passwordHash) {
            return true;
        }

        credentials[_user].failedAttempts += 1;
        credentials[_user].lastAttempt = block.timestamp;
        _logAudit(_user, keccak256("AUTH_FAILURE"), false);

        if (credentials[_user].failedAttempts >= MAX_ATTEMPTS) {
            credentials[_user].locked = true;
            emit AccountLocked(_user, block.timestamp + LOCKOUT_DURATION);
        }
        return false;
    }

    function getFailedAttempts(address _user) external view returns (uint8) {
        return credentials[_user].failedAttempts;
    }

    function isLocked(address _user) external view returns (bool) {
        return credentials[_user].locked;
    }

    function getAuditLogLength() external view returns (uint256) {
        return auditLog.length;
    }

    function _logAudit(address _actor, bytes32 _action, bool _success) internal {
        auditLog.push(AuditEntry({
            actor: _actor,
            action: _action,
            timestamp: block.timestamp,
            success: _success
        }));
        emit AuditLogged(auditLog.length - 1, _actor);
    }

    function getBalance(address _user) external view returns (uint256) {
        return balances[_user];
    }
}
